   136→    fn commit_transaction(
   137→        &mut self,
   138→        output: ResultAndState<<Self::Evm as Evm>::HaltReason>,
   139→        tx: impl ExecutableTx<Self>,
   140→    ) -> Result<u64, BlockExecutionError> {
